#!/usr/bin/env bash
# Render the public comparison page's content (tracker issue #147) from the
# COMMITTED runner artifacts — the same no-hand-typed-numbers discipline as
# scripts/render-conformance-stats.sh (CI: scripts/check-conformance-numbers.sh).
#
# Inputs (all committed, regenerated by the conformance/benchmark harnesses):
#   docs/conformance/{ehrbase-rs,ehrbase-java}/{results.json,badge-*.json}
#   docs/benchmarks/{ehrbase-rs,ehrbase-java}/{results.json,knee.json}
#   docs/benchmarks/charts/comparison-*.svg   (harness-rendered overlays)
# Outputs:
#   website/book/generated/comparison-conformance.md
#   website/book/generated/comparison-bench.md
#   website/book/src/comparison-assets/*.svg  (copied; gitignored)
set -euo pipefail
cd "$(dirname "$0")/.."

RS="docs/conformance/ehrbase-rs"
JV="docs/conformance/ehrbase-java"
BRS="docs/benchmarks/ehrbase-rs"
BJV="docs/benchmarks/ehrbase-java"
OUT="website/book/generated"

command -v jq >/dev/null 2>&1 || { echo "render-comparison: jq is required" >&2; exit 1; }
for f in "$RS/results.json" "$JV/results.json" "$BRS/knee.json" "$BJV/knee.json" \
  "$BRS/results.json" "$BJV/results.json"; do
  [ -f "$f" ] || { echo "render-comparison: missing artifact $f" >&2; exit 1; }
done
mkdir -p "$OUT" website/book/src/comparison-assets

count() { jq "[.cases[] | select(.status == \"$2\")] | length" "$1/results.json"; }
# Badge messages differ by verdict: "PASS (9/9 capabilities)" vs the
# no-verdict "3/9 capabilities" form a failing profile gets — render the
# latter as "not met (3/9)".
verdict() {
  local msg
  msg=$(jq -r '.message' "$1")
  case "$msg" in
    PASS*|FAIL*|OBTAINED*) echo "${msg%% *}" ;;
    *) echo "not met (${msg%% *})" ;;
  esac
}

# ── conformance side ─────────────────────────────────────────────────────────
rs_date=$(jq -r '.started' "$RS/results.json" | cut -dT -f1)
jv_date=$(jq -r '.started' "$JV/results.json" | cut -dT -f1)
jv_version=$(jq -r '.sut.product.version // .sut.product.name' "$JV/results.json")
rs_total=$(jq '.cases | length' "$RS/results.json")
jv_total=$(jq '.cases | length' "$JV/results.json")

# Shared-catalogue outcomes: the upstream run predates the newest catalogue
# additions, so the honest comparison runs over the intersection of
# (case id, format) keys; jq joins via INDEX.
shared=$(jq -n --slurpfile a "$RS/results.json" --slurpfile b "$JV/results.json" '
  (INDEX($a[0].cases[]; "\(.id)|\(.format)")) as $rs
  | [$b[0].cases[] | select($rs["\(.id)|\(.format)"] != null)
     | {key: "\(.id)|\(.format)", java: .status, rs: $rs["\(.id)|\(.format)"].status}]')
shared_n=$(echo "$shared" | jq 'length')
srow() { echo "$shared" | jq "[.[] | select(.$1 == \"$2\")] | length"; }

# Upstream failures grouped by capability, and the full per-case list with
# our outcome on the identical case.
fail_by_cap=$(jq -n --slurpfile b "$JV/results.json" '
  [$b[0].cases[] | select(.status=="failed")] | group_by(.capability)
  | map({cap: .[0].capability, n: length}) | sort_by(-.n)')
fail_rows=$(jq -rn --slurpfile a "$RS/results.json" --slurpfile b "$JV/results.json" '
  (INDEX($a[0].cases[]; "\(.id)|\(.format)")) as $rs
  | [$b[0].cases[] | select(.status=="failed")]
  | sort_by(.ecc_id, .format)[]
  | "| \(.ecc_id) | \(.title | gsub("\\|"; "\\\\|")) | \(.format) | \($rs["\(.id)|\(.format)"].status // "not in shared set") |"')

{
  cat <<EOF
Runs compared: **ehrbase-rs** (run of ${rs_date}, ${rs_total} case-by-format
executions of the current catalogue) vs **${jv_version}** (run of ${jv_date},
${jv_total} executions — the catalogue as it stood at that run; the newer
cases are excluded from the shared table below). Every number on this page is
read from the committed \`results.json\`/badge artifacts of those runs.

| | executed | passed | failed | errored | skipped | N/A | CORE | STANDARD | OPTIONS |
|---|---|---|---|---|---|---|---|---|---|
| **ehrbase-rs** | ${rs_total} | $(count "$RS" passed) | $(count "$RS" failed) | $(count "$RS" errored) | $(count "$RS" skipped) | $(count "$RS" notapplicable) | $(verdict "$RS/badge-core.json") | $(verdict "$RS/badge-standard.json") | $(verdict "$RS/badge-options.json") |
| **upstream (Java)** | ${jv_total} | $(count "$JV" passed) | $(count "$JV" failed) | $(count "$JV" errored) | $(count "$JV" skipped) | $(count "$JV" notapplicable) | $(verdict "$JV/badge-core.json") | $(verdict "$JV/badge-standard.json") | $(verdict "$JV/badge-options.json") |

On the **${shared_n} case-by-format executions both runs share**:

| | passed | failed | skipped | N/A |
|---|---|---|---|---|
| **ehrbase-rs** | $(srow rs passed) | $(srow rs failed) | $(srow rs skipped) | $(srow rs notapplicable) |
| **upstream (Java)** | $(srow java passed) | $(srow java failed) | $(srow java skipped) | $(srow java notapplicable) |

### Upstream failures by capability

| Capability | failed cases |
|---|---|
$(echo "$fail_by_cap" | jq -r '.[] | "| \(.cap) | \(.n) |"')

<details><summary>Every upstream-failed case, with the ehrbase-rs outcome on the identical case</summary>

| ECC id | Case | Format | ehrbase-rs outcome |
|---|---|---|---|
${fail_rows}

</details>
EOF
} > "$OUT/comparison-conformance.md"

# ── benchmark side ───────────────────────────────────────────────────────────
kfield() { jq -r ".knee.$2" "$1/knee.json"; }
kround() { jq -r ".knee.$2 | round" "$1/knee.json"; }
p99ms() { jq -r '(.knee.p99_us / 1000) | round' "$1/knee.json"; }
rss_mb() { jq -r "(.resources.app.$2 / 1048576) | round" "$1/results.json"; }
scale=$(jq -r '.scale' "$BRS/knee.json")

{
  cat <<EOF
Identical clinical workload, identical client, identical host, database
pre-seeded to the **${scale}** scale rung — the knee is the last load step
sustained inside the SLO (p99 ≤ 1 s, errors ≤ 0.1%). Read from the committed
\`knee.json\`/\`results.json\` pairs; the curves are the benchmark harness's
own rendered artifacts.

| | max sustained throughput | p99 at the knee | knee load factor | idle RSS | peak RSS |
|---|---|---|---|---|---|
| **ehrbase-rs** | $(kround "$BRS" rps) req/s | $(p99ms "$BRS") ms | $(kfield "$BRS" load_factor) | $(rss_mb "$BRS" idle_rss) MB | $(rss_mb "$BRS" peak_rss) MB |
| **upstream (Java)** | $(kround "$BJV" rps) req/s | $(p99ms "$BJV") ms | $(kfield "$BJV" load_factor) | $(rss_mb "$BJV" idle_rss) MB | $(rss_mb "$BJV" peak_rss) MB |

### The knee — sustained throughput ladder

![Knee comparison](./comparison-assets/comparison-knee.svg)

### Latency and throughput overlays

![p99 comparison](./comparison-assets/comparison-p99.svg)

![p50 comparison](./comparison-assets/comparison-p50.svg)

![Throughput comparison](./comparison-assets/comparison-throughput.svg)

### Resources

![Memory comparison](./comparison-assets/comparison-memory.svg)

![CPU comparison](./comparison-assets/comparison-cpu.svg)

![Cold start comparison](./comparison-assets/comparison-coldstart.svg)
EOF
} > "$OUT/comparison-bench.md"

# The harness-rendered overlay SVGs, copied into the book tree (gitignored).
cp docs/benchmarks/charts/comparison-*.svg website/book/src/comparison-assets/

echo "render-comparison: wrote $OUT/comparison-{conformance,bench}.md + $(ls website/book/src/comparison-assets | wc -l | tr -d ' ') chart assets"
